-- EXPLAIN ANALYZE of MERGE counts each node of its join: the scans, the
-- Hash (its rows and table size) and the join itself, with the rows each
-- condition removed; MERGE reports what its actions did with the join's
-- rows. A hash join that keeps no unmatched inner row stops when either
-- relation is empty, reading the outer one first when that is cheaper.
-- Each relation's own ON conditions filter its scan, unless the join keeps
-- its unmatched rows.
CREATE TABLE t652 (id int, v int);
INSERT INTO t652 SELECT g, g FROM generate_series(1, 1000) g;
CREATE TABLE s652 (k int, w int);
INSERT INTO s652 SELECT g, g FROM generate_series(1, 1000) g;
CREATE TABLE small652 (k int, w int);
INSERT INTO small652 SELECT (g % 20) * 7, g FROM generate_series(1, 40) g;
INSERT INTO small652 VALUES (NULL, 99), (2000, 1), (2001, 2);
CREATE TABLE e652 (k int, w int);
CREATE TABLE big652 (k int, w int);
INSERT INTO big652 SELECT g % 2000, g FROM generate_series(1, 3000) g;
CREATE TABLE p652 (id int, v int) PARTITION BY RANGE (id);
CREATE TABLE p652_1 PARTITION OF p652 FOR VALUES FROM (0) TO (500);
CREATE TABLE p652_2 PARTITION OF p652 FOR VALUES FROM (500) TO (3000);
INSERT INTO p652 SELECT g, g FROM generate_series(1, 1000) g;
ANALYZE t652;
ANALYZE s652;
ANALYZE small652;
ANALYZE e652;
ANALYZE big652;
ANALYZE p652;
-- First, while the planner's estimates are the analyzed ones.
BEGIN;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF)
  MERGE INTO t652 USING big652 ON t652.id = big652.k
  WHEN MATCHED AND big652.w > 1000 THEN UPDATE SET v = 0
  WHEN NOT MATCHED BY SOURCE THEN UPDATE SET v = -1;
ROLLBACK;
BEGIN;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF)
  MERGE INTO t652 USING small652 ON t652.id = small652.k
  WHEN MATCHED AND small652.w > 20 THEN UPDATE SET v = small652.w
  WHEN NOT MATCHED THEN INSERT VALUES (small652.k, small652.w);
ROLLBACK;
BEGIN;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF)
  MERGE INTO t652 USING small652 ON t652.id = small652.k
  WHEN MATCHED AND small652.w > 20 THEN DELETE
  WHEN NOT MATCHED BY SOURCE AND t652.id < 30 THEN UPDATE SET v = -1;
ROLLBACK;
BEGIN;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF)
  MERGE INTO p652 USING small652 ON p652.id = small652.k
  WHEN MATCHED AND small652.w > 30 THEN UPDATE SET v = -small652.w
  WHEN NOT MATCHED AND small652.k IS NOT NULL THEN INSERT VALUES (small652.k, small652.w);
ROLLBACK;
BEGIN;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF)
  MERGE INTO t652 USING small652 ON t652.id = small652.k
  AND small652.w > 23 AND t652.v < 500 WHEN MATCHED THEN UPDATE SET v = small652.w;
ROLLBACK;
BEGIN;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF)
  MERGE INTO small652 USING t652 ON t652.id = small652.k
  WHEN MATCHED THEN UPDATE SET w = t652.v WHEN NOT MATCHED THEN DO NOTHING;
ROLLBACK;
BEGIN;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF)
  MERGE INTO t652 USING s652 ON t652.id = s652.k
  WHEN MATCHED AND s652.w % 3 = 0 THEN DELETE WHEN MATCHED THEN UPDATE SET v = t652.v + 1
  RETURNING merge_action(), t652.id;
ROLLBACK;
BEGIN;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF)
  MERGE INTO t652 USING (VALUES (5, 1), (6, 2), (5000, 3)) v(k, w) ON t652.id = v.k
  WHEN MATCHED THEN UPDATE SET v = v.w WHEN NOT MATCHED THEN INSERT VALUES (v.k, v.w);
ROLLBACK;
BEGIN;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF, VERBOSE)
  MERGE INTO t652 USING small652 ON t652.id = small652.k AND t652.v + small652.w > 50
  WHEN MATCHED AND small652.w > 20 THEN UPDATE SET v = small652.w
  WHEN NOT MATCHED BY SOURCE AND t652.id < 10 THEN DELETE;
ROLLBACK;
BEGIN;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF)
  MERGE INTO t652 USING e652 ON t652.id = e652.k WHEN MATCHED THEN DELETE;
ROLLBACK;
BEGIN;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF)
  MERGE INTO t652 USING e652 ON t652.id = e652.k
  WHEN NOT MATCHED BY SOURCE AND t652.id < 3 THEN DELETE;
ROLLBACK;
BEGIN;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF)
  MERGE INTO e652 USING t652 ON t652.id = e652.k WHEN MATCHED THEN DELETE;
ROLLBACK;
BEGIN;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF)
  MERGE INTO e652 USING t652 ON t652.id = e652.k
  WHEN NOT MATCHED AND t652.id < 3 THEN INSERT VALUES (t652.id, t652.v);
ROLLBACK;
BEGIN;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF)
  MERGE INTO p652 USING big652 ON p652.id = big652.k
  WHEN MATCHED AND big652.w > 2500 THEN UPDATE SET v = 0;
ROLLBACK;
BEGIN;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF)
  MERGE INTO p652 USING small652 ON p652.id = small652.k AND p652.id < 100
  WHEN MATCHED AND small652.w > 20 THEN UPDATE SET v = small652.w;
ROLLBACK;
BEGIN;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF)
  MERGE INTO t652 USING small652 ON t652.id = small652.k
  WHEN MATCHED THEN DO NOTHING WHEN NOT MATCHED BY SOURCE THEN DELETE
  WHEN NOT MATCHED THEN INSERT VALUES (small652.k, small652.w);
ROLLBACK;
BEGIN;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF)
  MERGE INTO t652 USING small652 ON t652.id = small652.k AND small652.w > 30
  WHEN NOT MATCHED THEN INSERT VALUES (small652.k, small652.w);
ROLLBACK;
BEGIN;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF, FORMAT JSON)
  MERGE INTO p652 USING small652 ON p652.id = small652.k
  WHEN MATCHED AND small652.w > 20 THEN DELETE;
ROLLBACK;
BEGIN;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF, FORMAT YAML)
  MERGE INTO t652 USING small652 ON t652.id = small652.k
  WHEN MATCHED AND small652.w > 20 THEN UPDATE SET v = 0
  WHEN NOT MATCHED THEN INSERT VALUES (small652.k, 0);
ROLLBACK;
